type_tree.macro:
macro_rules! create_array {
    (@from Boolean) => { ... };
    (@from Int8) => { ... };
    (@from Int16) => { ... };
    (@from Int32) => { ... };
    (@from Int64) => { ... };
    (@from UInt8) => { ... };
    (@from UInt16) => { ... };
    (@from UInt32) => { ... };
    (@from UInt64) => { ... };
    (@from Float16) => { ... };
    (@from Float32) => { ... };
    (@from Float64) => { ... };
    (@from Utf8) => { ... };
    (@from Utf8View) => { ... };
    (@from LargeUtf8) => { ... };
    (@from IntervalDayTime) => { ... };
    (@from IntervalYearMonth) => { ... };
    (@from Second) => { ... };
    (@from Millisecond) => { ... };
    (@from Microsecond) => { ... };
    (@from Nanosecond) => { ... };
    (@from Second32) => { ... };
    (@from Millisecond32) => { ... };
    (@from Microsecond64) => { ... };
    (@from Nanosecond64) => { ... };
    (@from DurationSecond) => { ... };
    (@from DurationMillisecond) => { ... };
    (@from DurationMicrosecond) => { ... };
    (@from DurationNanosecond) => { ... };
    (@from Decimal32) => { ... };
    (@from Decimal64) => { ... };
    (@from Decimal128) => { ... };
    (@from Decimal256) => { ... };
    (@from TimestampSecond) => { ... };
    (@from TimestampMillisecond) => { ... };
    (@from TimestampMicrosecond) => { ... };
    (@from TimestampNanosecond) => { ... };
    (@from $ty: ident) => { ... };
    (Null, $size: expr) => { ... };
    (Binary, [$($values: expr),*]) => { ... };
    (LargeBinary, [$($values: expr),*]) => { ... };
    ($ty: tt, [$($values: expr),*]) => { ... };
    (Binary, $values: expr) => { ... };
    (LargeBinary, $values: expr) => { ... };
    ($ty: tt, $values: expr) => { ... };
}
